from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, KeepTogether
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.pdfbase import pdfmetrics
from reportlab.lib.colors import HexColor
import os

OUT = 'output/pdf/guia-pedidos-amizade-arcadia.pdf'
os.makedirs(os.path.dirname(OUT), exist_ok=True)
font = r'C:\Windows\Fonts\arial.ttf'
font_b = r'C:\Windows\Fonts\arialbd.ttf'
if os.path.exists(font) and os.path.exists(font_b):
    pdfmetrics.registerFont(TTFont('Guide', font)); pdfmetrics.registerFont(TTFont('Guide-Bold', font_b)); F, FB = 'Guide', 'Guide-Bold'
else: F, FB = 'Helvetica', 'Helvetica-Bold'
navy, teal, muted, light = HexColor('#13243A'), HexColor('#147D78'), HexColor('#536579'), HexColor('#EFF5F6')
s = getSampleStyleSheet()
s.add(ParagraphStyle(name='Cover',fontName=FB,fontSize=26,leading=32,textColor=colors.white,alignment=1))
s.add(ParagraphStyle(name='Sub',fontName=F,fontSize=12,leading=18,textColor=HexColor('#D8E8EE'),alignment=1))
s.add(ParagraphStyle(name='H1x',fontName=FB,fontSize=18,leading=23,textColor=navy,spaceBefore=7,spaceAfter=8,keepWithNext=True))
s.add(ParagraphStyle(name='H2x',fontName=FB,fontSize=12,leading=15,textColor=teal,spaceBefore=7,spaceAfter=4,keepWithNext=True))
s.add(ParagraphStyle(name='Bodyx',fontName=F,fontSize=9.3,leading=13.7,textColor=navy,spaceAfter=5))
s.add(ParagraphStyle(name='Smallx',fontName=F,fontSize=8,leading=11,textColor=muted,spaceAfter=4))
s.add(ParagraphStyle(name='CodeX',fontName='Courier',fontSize=7.5,leading=10.5,textColor=navy,backColor=light,borderPadding=7,spaceBefore=4,spaceAfter=7))
s.add(ParagraphStyle(name='Cellx',fontName=F,fontSize=8.1,leading=11,textColor=navy))
s.add(ParagraphStyle(name='Headx',fontName=FB,fontSize=8.3,leading=11,textColor=colors.white))
def P(t,sty='Bodyx'): return Paragraph(t,s[sty])
def footer(c,d):
    c.saveState(); w,h=A4; c.setStrokeColor(HexColor('#DCE5E9')); c.line(18*mm,15*mm,w-18*mm,15*mm); c.setFont(F,8); c.setFillColor(muted); c.drawString(18*mm,10*mm,'Arcadia | Guia técnico de pedidos de amizade'); c.drawRightString(w-18*mm,10*mm,str(d.page)); c.restoreState()
doc=SimpleDocTemplate(OUT,pagesize=A4,rightMargin=19*mm,leftMargin=19*mm,topMargin=18*mm,bottomMargin=22*mm,title='Como funcionam os pedidos de amizade no Arcadia',author='OpenAI')
story=[]
cover=Table([[P('PEDIDOS DE<br/>AMIZADE','Cover')],[P('Como MySQL, PHP e JavaScript trabalham em conjunto no Arcadia','Sub')]],colWidths=[172*mm],rowHeights=[55*mm,29*mm])
cover.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),navy),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('LEFTPADDING',(0,0),(-1,-1),12),('RIGHTPADDING',(0,0),(-1,-1),12)]))
story += [Spacer(1,27*mm),cover,Spacer(1,12*mm),P('Este guia acompanha o percurso de um pedido: desde o clique em “Adicionar amigo”, passando pela API e pela base de dados, até à aceitação ou recusa na interface.'),P('Baseado nos ficheiros atuais: database/schema.sql, includes/bootstrap.php, api/friends.php, assets/js/app.js e index.php.','Smallx'),Spacer(1,18*mm),P('Visão geral','H2x')]
flow=Table([[P('<b>JavaScript</b><br/>regista ações e redesenha','Cellx'),P('→','H2x'),P('<b>PHP / API</b><br/>autentica, valida e grava','Cellx'),P('→','H2x'),P('<b>MySQL</b><br/>guarda relação e avisos','Cellx')]],colWidths=[48*mm,8*mm,48*mm,8*mm,48*mm])
flow.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),light),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('ALIGN',(1,0),(1,0),'CENTER'),('ALIGN',(3,0),(3,0),'CENTER'),('BOX',(0,0),(-1,-1),.5,HexColor('#D8E4E8')),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7)]))
story += [flow,PageBreak(),P('1. O modelo de dados no MySQL','H1x'),P('A tabela <b>friendships</b> representa pedidos pendentes e amizades aceites. Cada par de utilizadores tem no máximo uma linha: o estado e os campos direcionais indicam em que fase está a relação.'),P('Campos principais','H2x')]
rows=[[P('Campo','Headx'),P('Função','Headx')],[P('<b>user_one, user_two</b>','Cellx'),P('Par ordenado numericamente (menor ID primeiro). A chave primária composta impede duplicar o par, mesmo se a ordem do pedido for invertida.','Cellx')],[P('<b>requester_id</b>','Cellx'),P('Utilizador que iniciou o pedido.','Cellx')],[P('<b>recipient_id</b>','Cellx'),P('Utilizador que recebeu o pedido.','Cellx')],[P('<b>status</b>','Cellx'),P('<b>pending</b>: à espera de resposta. <b>accepted</b>: amizade confirmada.','Cellx')],[P('<b>created_at / updated_at</b>','Cellx'),P('Data de criação e última alteração. updated_at atualiza automaticamente.','Cellx')]]
t=Table(rows,colWidths=[42*mm,130*mm],repeatRows=1); t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),teal),('GRID',(0,0),(-1,-1),.35,HexColor('#CAD8DE')),('VALIGN',(0,0),(-1,-1),'TOP'),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,HexColor('#F7FAFB')]),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6)]))
story += [t,Spacer(1,6),P('Exemplo: se a pessoa 14 pede amizade à pessoa 39, guardamos user_one=14, user_two=39, requester_id=14, recipient_id=39 e status=pending. Ao aceitar, basta mudar status para accepted; os campos direcionais preservam quem enviou o primeiro pedido.'),P('Há índices por recipient_id/status e requester_id/status para localizar rapidamente pedidos recebidos e enviados. As chaves estrangeiras ligam os participantes à tabela users e eliminam relações se uma conta for apagada (ON DELETE CASCADE).','Bodyx'),P('A tabela <b>notifications</b> guarda quem recebe o aviso, quem o provocou, o tipo (friend_request ou friend_accepted), o texto, o estado de leitura e a data.','Bodyx'),P('2. O PHP: API e regras de negócio','H1x'),P('O ficheiro <b>api/friends.php</b> recebe pedidos HTTP e devolve JSON. Abre a ligação PDO, exige uma sessão autenticada e verifica o método. As consultas preparadas passam valores como parâmetros em vez de concatená-los ao SQL.'),P('Leituras via GET','H2x'),P('Sem parâmetros, devolve amigos aceites, pedidos recebidos e pedidos enviados. <b>?q=...</b> pesquisa por nome ou ID público e inclui o estado da relação; <b>?suggested=1</b> lista sugestões sem relação anterior; <b>?profile=ID</b> devolve perfil, jogos e coleções apenas quando a amizade já foi aceite.'),P('Alterações via POST','H2x'),P('As ações POST exigem sessão, token CSRF válido, um user_id inteiro e diferente do próprio utilizador. A API normaliza o par por min/max e então aplica a regra da ação:')]
acts=[[P('Ação','Headx'),P('O que acontece','Headx')],[P('<b>send</b>','Cellx'),P('Cria uma relação pending e avisa o destinatário. Se já houver pedido pendente inverso, aceita-o diretamente. Relação já existente resulta em conflito.','Cellx')],[P('<b>accept</b>','Cellx'),P('Confirma que o utilizador atual é o destinatário, muda para accepted, marca o pedido como lido e avisa quem pediu.','Cellx')],[P('<b>decline</b>','Cellx'),P('Apaga o pedido recebido pendente e marca a notificação como lida.','Cellx')],[P('<b>cancel</b>','Cellx'),P('Apaga o pedido ainda pendente enviado pelo próprio utilizador e atualiza a notificação.','Cellx')],[P('<b>remove</b>','Cellx'),P('Apaga a relação aceite entre os dois utilizadores.','Cellx')]]
story.append(PageBreak())
t=Table(acts,colWidths=[32*mm,140*mm],repeatRows=1); t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),teal),('GRID',(0,0),(-1,-1),.35,HexColor('#CAD8DE')),('VALIGN',(0,0),(-1,-1),'TOP'),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,HexColor('#F7FAFB')]),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6)]))
story += [t,Spacer(1,5),P('Mudanças relacionadas são agrupadas em transações: PHP inicia, atualiza amizade/notificação e confirma; perante erro, faz rollback. A API responde com códigos HTTP, como 401 (sem sessão), 403 (sem permissão), 404 (relação inexistente), 409 (conflito) e 422 (dados inválidos).'),P('3. O JavaScript: interação e atualização','H1x'),P('Em <b>assets/js/app.js</b>, o estado em memória mantém listas de amigos e pedidos, resultados da pesquisa e separador selecionado. A função request() usa fetch(), interpreta JSON e converte respostas de erro em mensagens para a interface.'),P('Ao abrir Amigos, o JS carrega listas e sugestões. A pesquisa aguarda 180 ms após a última tecla, exige pelo menos dois caracteres e codifica o termo na URL. Um contador de pesquisas ignora respostas antigas que cheguem atrasadas. Conteúdo textual é escapado antes de inserir HTML.'),P('Os cartões mostram as ações permitidas conforme o estado. Um listener de clique identifica data-friend-action. Recusar, cancelar e remover pedem confirmação. Depois o JS envia POST com action, user_id e token CSRF; quando termina, atualiza listas, sugestões, resultados e notificações sem recarregar toda a página.'),PageBreak()]
story += [P('4. Percurso de um pedido','H1x')]
steps=[('1. Encontrar','A pesquisa um nome/ID ou escolhe uma sugestão; o browser faz GET à API.'),('2. Enviar','O clique em “Adicionar amigo” produz POST com action=send, o ID de B e o token CSRF.'),('3. Validar','PHP exige sessão, valida CSRF, verifica o ID, impede adicionar a própria conta e confirma que B existe.'),('4. Gravar','A API ordena os IDs do par, verifica se já existe relação e cria status=pending. Na mesma transação cria uma notificação para B.'),('5. Atualizar','A resposta JSON chega ao JS. A interface carrega os dados recentes e mostra “Pedido enviado”; B verá o pedido recebido e o contador.'),('6. Responder','Ao aceitar, status muda para accepted e A é notificado. Ao recusar, a linha pending é apagada. A pode cancelar enquanto continua pendente.'),('7. Usar a amizade','Ambos aparecem na lista de amigos. Perfil partilhado e chat são acessíveis após aceitação.')]
for h,b in steps: story.append(KeepTogether([P(h,'H2x'),P(b)]))
story += [P('Resumo técnico','H2x'),P('Browser: POST (ação, utilizador, CSRF) → PHP: autenticação e validação → MySQL: verificar/criar/alterar friendships → MySQL: atualizar notifications → PHP: JSON → JS: atualizar estado e interface.','CodeX'),P('5. Segurança e resumo','H1x'),P('<b>Autenticação:</b> operações exigem sessão. <b>CSRF:</b> token ligado à sessão acompanha POST. <b>SQL injection:</b> PDO com parâmetros preparados. <b>Autorização:</b> só destinatário aceita/recusa; apenas remetente cancela; perfil exige amizade aceite. <b>Integridade:</b> chave composta com IDs ordenados evita relações duplicadas. <b>Consistência:</b> transações agrupam a relação e os avisos.'),P('MySQL guarda o estado persistente. PHP decide se uma transição é permitida e grava-a. JavaScript apresenta os dados e envia ações; não é ele quem decide se alguém é amigo, porque o servidor valida cada operação.'),P('Referências consultadas: Arcadia/database/schema.sql; Arcadia/includes/bootstrap.php; Arcadia/api/friends.php; Arcadia/assets/js/app.js; Arcadia/index.php. Documento descritivo da implementação encontrada, sem alterações ao código da aplicação.','Smallx')]
doc.build(story,onFirstPage=footer,onLaterPages=footer)
print(os.path.abspath(OUT))
